/**
 * Parity suite for the micro-skills port.
 *
 * `tests/parity/microskills_vectors.json` is generated by the PINNED upstream Python
 * implementation (see `generate_microskills_vectors.py`); this test replays every vector
 * against the TypeScript port and asserts identical results. When the JSON is absent (the
 * upstream checkout is not vendored in this environment) the suite SKIPS cleanly instead of
 * failing: the unit suite in `tests/microskills.test.mjs` is the always-on gate.
 */
import { existsSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import assert from 'node:assert/strict'
import test from 'node:test'

import * as O from '../../lib/microskills/observe.js'
import * as E from '../../lib/microskills/envfacts.js'
import * as L from '../../lib/microskills/lifecycle.js'
import * as D from '../../lib/microskills/distiller.js'

const here = dirname(fileURLToPath(import.meta.url))
const vectorsPath = join(here, 'microskills_vectors.json')

const missing = !existsSync(vectorsPath)
const vectors = missing ? null : JSON.parse(readFileSync(vectorsPath, 'utf8'))
const skip = missing
  ? 'microskills_vectors.json absent: run tests/parity/generate_microskills_vectors.py with the pinned upstream checkout'
  : false

const vocab = (name) => (name === 'generic' ? O.GENERIC : O.PYTHON_GIT)

function obsData(observation) {
  return {
    call: observation.call,
    intent: observation.intent,
    form: observation.form,
    head: observation.head,
    prefix: observation.prefix,
    segment: observation.segment,
    hosts: [...observation.hosts],
    probe: observation.probe,
    outcome: observation.outcome,
    labels: [...observation.labels],
    label_err: observation.labelErr,
    loaded: observation.loaded,
    tests_ran: observation.testsRan,
    env: observation.env,
    not_found: observation.notFound,
  }
}

function digestData(digest) {
  return {
    obs: digest.obs.map(obsData),
    edited: [...digest.edited],
    n_calls: digest.nCalls,
    env: digest.env.map((call) => ({
      call: call.call,
      need: [...call.need],
      sets: { ...call.sets },
      ok: call.ok,
    })),
  }
}

/** The calls a vector carries, in the shape the port consumes. */
function callsOf(rows) {
  return rows.map((row) => ({
    name: row.name,
    args: row.args,
    output: row.output,
    isError: row.isError,
    turn: 0,
    step: 0,
    at: '2026-01-01T00:00:00.000Z',
    callId: `c-${row.name}`,
  }))
}

function digestFromCalls(row) {
  return O.observeTask(callsOf(row.calls), {
    vocab: vocab(row.vocab),
    cwds: row.calls.map((call) => call.cwd),
    root: row.root,
    top: row.top,
  })
}

function lifeData(fact) {
  return fact.life.toDict()
}

function factData(fact) {
  return {
    id: fact.id,
    family: fact.family,
    high: fact.life.high,
    drift: fact.life.drift,
    params: fact.params,
    life: lifeData(fact),
    state: fact.state,
    claim: fact.claim(),
  }
}

test('micro-skills parity vectors', { skip }, async (t) => {
  await t.test('unwrap', () => {
    for (const item of vectors.unwrap) assert.equal(O.unwrap(item.in), item.out, item.in)
  })

  await t.test('segments', () => {
    for (const item of vectors.segments) assert.deepEqual(O.segments(item.in), item.out, item.in)
  })

  await t.test('error_class', () => {
    for (const item of vectors.error_class) assert.equal(O.errorClass(item.in), item.out, item.in)
  })

  await t.test('exit_code_hint', () => {
    for (const item of vectors.exit_hint) assert.equal(O.exitCodeHint(item.in), item.out, item.in)
  })

  await t.test('label_rule', () => {
    for (const item of vectors.label_rule) {
      assert.deepEqual(O.labelRule(item.a, item.b), item.out, `${item.a} -> ${item.b}`)
    }
  })

  await t.test('classify_command', () => {
    for (const item of vectors.classify) {
      const got = O.classifyCommand(item.cmd, {
        callIndex: item.call_index,
        vocab: vocab(item.vocab),
        cwd: item.cwd,
        root: item.root,
        top: item.top,
      }).map(obsData)
      assert.deepEqual(got, item.obs, item.cmd)
    }
  })

  await t.test('observeTask digests', () => {
    for (const row of vectors.observe) {
      assert.deepEqual(digestData(digestFromCalls(row)), row.digest, row.name)
    }
  })

  await t.test('lifecycle state machine', () => {
    for (const row of vectors.lifecycle) {
      const life = new L.Lifecycle(row.name, row.high, row.drift)
      for (const step of row.steps) {
        life.update(step.now, step.verdict, step.fired, step.exercised, step.files)
      }
      assert.deepEqual(life.toDict(), row.final, row.name)
      assert.equal(life.injectable(), row.injectable, `${row.name} injectable`)
      assert.equal(Math.round(life.score(row.now) * 1e12) / 1e12, row.score, `${row.name} score`)
    }
  })

  await t.test('env fact claims and render', () => {
    for (const row of vectors.env_claims) {
      const spec = row.spec
      const fact = new E.EnvFact(spec.id, spec.family, spec.high, JSON.parse(JSON.stringify(spec.params)))
      for (const step of spec.steps) {
        E.fold(fact, step.now, step.verdict, step.fired, step.exercised, [])
      }
      assert.deepEqual(fact.params, row.params, `${row.spec.id} params`)
      assert.equal(fact.claim(), row.claim, `${row.spec.id} claim`)
      assert.equal(fact.state, row.state, `${row.spec.id} state`)
      assert.equal(fact.injectable(), row.injectable, `${row.spec.id} injectable`)
      assert.deepEqual(fact.life.toDict(), row.life, `${row.spec.id} life`)
      const distiller = new E.EnvFactsDistiller({ vocab: O.GENERIC })
      distiller.facts.set(fact.id, fact)
      const render = distiller.render()
      assert.equal(render, row.render, `${row.spec.id} render`)
      assert.deepEqual([...distiller.lastInjected].sort(), row.injected, `${row.spec.id} injected`)
    }
  })

  await t.test('env fact update sequences', () => {
    for (const row of vectors.env_update) {
      const digest = digestFromCalls(row)
      assert.deepEqual(digestData(digest), row.digest, `${row.name} digest`)
      const distiller = new E.EnvFactsDistiller({ vocab: vocab(row.vocab) })
      row.snapshots.forEach((snapshot, index) => {
        distiller.seedInjected(row.injected[index])
        distiller.update(digest)
        assert.deepEqual(
          [...distiller.facts.values()].map(factData),
          snapshot.facts,
          `${row.name} task ${index} facts`,
        )
        assert.equal(distiller.render(), snapshot.render, `${row.name} task ${index} render`)
        const verdicts = Object.fromEntries(
          Object.entries(distiller.lastDigest?.verdicts ?? {}).map(([id, value]) => [id, [...value]]),
        )
        assert.deepEqual(verdicts, snapshot.last_digest.verdicts, `${row.name} task ${index} verdicts`)
      })
    }
  })

  await t.test('templates', () => {
    for (const item of vectors.templates) assert.deepEqual(D.templates(item.in), item.out)
  })

  await t.test('error_signature', () => {
    for (const item of vectors.error_signature) {
      assert.equal(D.errorSignature(item.out, item.roots), item.sig, item.out)
    }
  })

  await t.test('relativeText', () => {
    for (const item of vectors.relative) assert.equal(D.relativeText(item.text, item.roots), item.out, item.text)
  })

  await t.test('distiller digests', () => {
    for (const row of vectors.digests) {
      const got = D.buildDigest(callsOf(row.calls), {
        iid: 't-0',
        resolved: true,
        generic: row.generic,
        startCwd: row.start,
        top: row.top,
      })
      assert.deepEqual(got, row.digest, row.name)
    }
  })

  await t.test('proposer prompts', () => {
    for (const row of vectors.proposer_prompts) {
      const digest = D.buildDigest(callsOf(row.calls), {
        iid: 't-0',
        resolved: true,
        generic: row.generic,
        startCwd: row.start,
        top: row.top,
      })
      const prompt = D.buildProposerPrompt('example/repo', [digest], row.existing, row.features, {
        rawExcerpts: row.excerpts,
        external: row.external,
        generic: row.generic,
      })
      assert.equal(prompt, row.prompt, row.name)
    }
  })

  await t.test('proposer system prompts', () => {
    assert.equal(D.PROPOSER_SYSTEM, vectors.proposer_system.default)
    assert.equal(D.PROPOSER_SYSTEM_GENERIC, vectors.proposer_system.generic)
    assert.deepEqual([...D.GENERIC_PREDICATES], vectors.proposer_system.generic_predicates)
  })

  await t.test('parse_payload', () => {
    for (const item of vectors.parse_payload) {
      const [extractors, facts] = D.parsePayload(item.raw)
      assert.deepEqual(extractors, item.extractors, item.raw)
      assert.deepEqual(facts, item.facts, item.raw)
    }
  })

  await t.test('detector verdicts', () => {
    for (const item of vectors.detectors) {
      const detector = new D.DetectorV3Scope(item.spec, item.features)
      assert.deepEqual(detector.verdict(item.digest), [item.verdict, item.fired, item.exercised], JSON.stringify(item.spec))
    }
  })

  await t.test('constants', () => {
    const want = vectors.constants
    assert.equal(L.K_PROMOTE, want.lifecycle.K_PROMOTE)
    assert.equal(L.GAMMA, want.lifecycle.GAMMA)
    assert.equal(L.LAMBDA, want.lifecycle.LAMBDA)
    assert.equal(L.SCORE_FLOOR, want.lifecycle.SCORE_FLOOR)
    assert.equal(L.HARD_KILL, want.lifecycle.HARD_KILL)
    assert.equal(L.FIRE_GATE, want.lifecycle.FIRE_GATE)
    assert.equal(L.FIRE_MIN_N, want.lifecycle.FIRE_MIN_N)
    assert.equal(E.STATE_SUBDIR, want.envfacts.STATE_SUBDIR)
    assert.equal(E.MAX_FACTS, want.envfacts.MAX_FACTS)
    assert.equal(E.MAX_TOKENS, want.envfacts.MAX_TOKENS)
    assert.equal(E.HEADER, want.envfacts.HEADER)
    assert.equal(E.GENERIC_HEADER, want.envfacts.GENERIC_HEADER)
    assert.equal(E.CONTRADICT_STREAK, want.envfacts.CONTRADICT_STREAK)
    assert.equal(D.PROPOSE_EVERY, want.distiller.PROPOSE_EVERY)
    assert.equal(D.WINDOW, want.distiller.WINDOW)
    assert.equal(D.MAX_CANDS, want.distiller.MAX_CANDS)
    assert.equal(D.MIN_CITE, want.distiller.MIN_CITE)
    assert.equal(D.MAX_EXTRACTORS, want.distiller.MAX_EXTRACTORS)
    assert.equal(D.RAW_SAMPLE, want.distiller.RAW_SAMPLE)
    assert.equal(D.ABSTAIN_GATE, want.distiller.ABSTAIN_GATE)
    assert.equal(D.STATE_SUBDIR, want.distiller.STATE_SUBDIR)
    assert.equal(D.BLOB_CAP, want.distiller.BLOB_CAP)
  })
})
